import{_ as r,C as i,o as n,c as l,ak as a,E as o,j as t,a as c}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"Segmented 分段控制器","description":"","frontmatter":{},"headers":[],"relativePath":"components/segmented.md","filePath":"components/segmented.md","lastUpdated":1790400917000}'),s={name:"components/segmented.md"};function h(b,d,m,u,g,p){const e=i("XhDemo");return n(),l("div",null,[d[0]||(d[0]=a('<h1 id="segmented-分段控制器" tabindex="-1">Segmented 分段控制器 <a class="header-anchor" href="#segmented-分段控制器" aria-label="Permalink to &quot;Segmented 分段控制器&quot;">​</a></h1><p>一排连在一起的互斥选项，选中的一段下方有一块滑动的指示器：淡底轨道里一块带描边的白色抬起面。它是单选组，参与表单提交。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/segmented" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/segmented.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/segmented" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/segmented" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/segmented.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一排互斥选项：root 是 radiogroup、每段是 radio；整组只占一个 Tab 位，进组后四个方向键都可移动</p>',5)),o(e,{src:"segmented/01-basic"}),d[1]||(d[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;segmented&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="受控" tabindex="-1">受控 <a class="header-anchor" href="#受控" aria-label="Permalink to &quot;受控&quot;">​</a></h3><p>传入 value 后由宿主决定；值可以是 null，表示没有任何一段选中</p>',6)),o(e,{src:"segmented/02-controlled"}),d[2]||(d[2]=t("h3",{id:"撑满行宽",tabindex:"-1"},[c("撑满行宽 "),t("a",{class:"header-anchor",href:"#撑满行宽","aria-label":'Permalink to "撑满行宽"'},"​")],-1)),d[3]||(d[3]=t("p",null,"block 使整组占满一行，各段等分剩余空间，长短不一的文字也能对齐",-1)),o(e,{src:"segmented/03-block"}),d[4]||(d[4]=t("h3",{id:"竖排",tabindex:"-1"},[c("竖排 "),t("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),d[5]||(d[5]=t("p",null,"orientation 只改变视觉排布，四个方向键与 Home/End 照常可用",-1)),o(e,{src:"segmented/04-vertical"}),d[6]||(d[6]=t("h3",{id:"禁用",tabindex:"-1"},[c("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[7]||(d[7]=t("p",null,"单段禁用仍可聚焦、仍是方向键的起点，只是无法选中它；整组禁用则全部不可修改",-1)),o(e,{src:"segmented/05-disabled"}),d[8]||(d[8]=t("h3",{id:"颜色",tabindex:"-1"},[c("颜色 "),t("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),d[9]||(d[9]=t("p",null,"tone 决定指示器与选中段文字使用哪族颜色，六种语气各一组",-1)),o(e,{src:"segmented/06-tone"}),d[10]||(d[10]=t("h3",{id:"尺寸",tabindex:"-1"},[c("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[11]||(d[11]=t("p",null,"size 改变段的高度、内边距与字号，指示器跟随测量得出的段",-1)),o(e,{src:"segmented/07-size"}),d[12]||(d[12]=t("h3",{id:"表单",tabindex:"-1"},[c("表单 "),t("a",{class:"header-anchor",href:"#表单","aria-label":'Permalink to "表单"'},"​")],-1)),d[13]||(d[13]=t("p",null,"提供 name 后才带上隐藏输入参与提交；宿主表单重置时，选中值回落到 default-value",-1)),o(e,{src:"segmented/08-form"}),d[14]||(d[14]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>二到五个平级选项之间切换：视图模式（列表 / 网格）、时间粒度（日 / 周 / 月）、排序方式。</li><li>选项少、名称短，且值得始终展开：分段控制器的价值在于不需要打开即可看到全部选项。</li><li>需要随表单一起提交该选择。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>选项超过六个，或选项文字长短悬殊时，改用<a href="./radio-group">单选组</a>竖排，或<a href="./select">选择器</a>收进浮层。</li><li>需要多选，或表达的是按钮的按下状态而不是一个字段值时，使用<a href="./toggle-group">切换按钮组</a>：它没有 <code>name</code>、不参与表单，也没有滑动指示器。</li><li>切换的是同一块区域的几屏内容时，使用<a href="./tabs">标签页</a>，它管理面板的显隐，不是一个值。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>集合入口：提供 <code>collection</code> 即只传数据，条目文本与禁用都以数据为准；需要改结构时再写部件。</li><li>受控与非受控两态齐全：提供 <code>value</code> 即受控，只发 <code>onValueChange</code> 不自行修改。</li><li>参与表单：提供 <code>name</code> 后隐藏输入才带上它；宿主表单重置时选中值回落到 <code>defaultValue</code>。隐藏输入只在只传 <code>collection</code>、由组件铺开结构时自动铺出；自行编写默认插槽排版时需要放一个隐藏输入部件，否则提供 <code>name</code> 也没有内容参与提交。</li><li>指示器位置由组件测量，横排竖排、ltr 与 rtl 使用同一条规则。</li><li>语气与尺寸两轴与其他组件同源；<code>block</code> 让整组撑满行宽、各段等分。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>放入<a href="./field">表单字段</a>，让标签、说明与错误文案一并接入。</li><li>与<a href="./tabs">标签页</a>搭配：分段控制器切换数据口径，标签页切换内容面板，两者不互相替代。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>各段文字长度尽量接近：长短悬殊时指示器滑动，整排宽度会跟着跳动。</li><li>段数固定后再使用：分段控制器不适合数量会变化的选项集。</li><li>选中态不只依靠指示器的颜色区分，文字色也要跟随变化，色觉障碍的用户才能分辨。</li><li>段的文字不走 <code>collection</code> 而是手写、且会在运行期改动时，改动后调用一次 <code>measure()</code>：指示器只跟随选中值、集合与根的尺寸变化，段内文字撑宽时它无法感知。</li><li>动态移除正持有焦点的段（例如按权限过滤）之后，焦点会回到 <code>&lt;body&gt;</code>。组件只保证 Tab 位退回容器、键盘可以再次进入；需要保持位置时由页面把焦点移到相邻的段。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>把它当按钮组使用：段是一个值的几个取值，不是几个动作。触发动作使用<a href="./button-group">按钮组</a>。</li><li>一行放七八段：那已经是下拉框，还占着整行宽度。</li><li>用它切换整页内容却不改地址：用户刷新后回到第一段。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-segmented&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSegmentedHiddenInput</code> <code>XhSegmentedIndicator</code> <code>XhSegmentedItem</code> <code>XhSegmentedItemText</code> <code>XhSegmentedRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSegmented</code></td></tr><tr><td>状态机</td><td><code>segmentedMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/segmented.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>SegmentedNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。提供后条目部件只需声明 value。 未提供时回到文本与禁用都写在条目部件上的方式。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中值。提供即受控：内部不再自行修改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用：条目全部 aria-disabled，点击与方向键都不生效。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：不可选择，但仍可聚焦、方向键照常移动焦点，对比度不降低。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改变呈现，不阻止交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起使用，只发无障碍属性，不自行拦截提交。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。提供后隐藏输入才带 name 并参与提交。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>视觉排布，默认 horizontal。方向键接受的轴与它无关（四个方向键恒响应）。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只改写左右方向键的语义与指示器的起始缘，上下键与之无关。 未提供时从根节点的计算样式读取（祖先链上的 dir 与 CSS direction 都计入），提供后以它为准。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键到达末尾是否回绕，默认 true。</td></tr><tr><td><code>block</code></td><td><code>boolean</code></td><td></td><td>撑满行宽，各段等分剩余空间。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: SegmentedValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控时随内部写入一并通知。</td></tr></tbody></table><h3 id="segmentednode" tabindex="-1">SegmentedNode <a class="header-anchor" href="#segmentednode" aria-label="Permalink to &quot;SegmentedNode&quot;">​</a></h3><p><code>collection</code> 的元素。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>展示文本；默认回退为 value。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>条目禁用：方向键跳过它，但它仍可聚焦、仍是导航起点。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>SegmentedValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSegmentedRoot</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhSegmentedRoot</code></td><td><code>item</code></td><td><code>SegmentedNodeMeta</code></td><td>铺开 collection 时每一段的文本插槽。</td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSegmentedItem</code></td><td><code>value</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>XhSegmentedItem</code></td><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>默认交给 connect 查询 collection，写死 false 会覆盖数据中的禁用。</td></tr><tr><td><code>XhSegmentedRoot</code></td><td><code>renderItem</code></td><td><code>(node: SegmentedNodeMeta) =&gt; ReactNode</code></td><td></td><td>每一段的自定义内容；未提供时使用 collection 中的 label。</td></tr><tr><td><code>XhSegmentedRoot</code></td><td><code>children</code></td><td><code>ReactNode</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>INDICATOR.MEASURE</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td>当前选中值；没有选中任何项时为 null。</td></tr><tr><td><code>collection</code></td><td><code>readonly SegmentedNodeMeta[]</code></td><td>由 collection 推导的条目元信息，按数据顺序排列；未提供 collection 时为空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>重新测量指示器。选中值变化与 collection 增删改名都会自动重新测量，根的尺寸变化由尺寸观察器接管； 以下情况需要手动调用：段的文字由部件手写（未经 collection）而后修改，或字体加载完成把段撑宽。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: SegmentedItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: SegmentedItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>选中值随这份原生输入提交。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点落到锚点段（即选中段），锚点缺席或被禁用时先落容器再由它转投首个可停留段</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in group, 组未禁用</td><td>焦点移到下一个可停留段并选中它（禁用段跳过、尽头按 loop 回绕）；只读时焦点照走但不落值；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in group, 组未禁用</td><td>焦点移到上一个可停留段并选中它；只读时焦点照走但不落值；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>focus in group, 组未禁用</td><td>焦点移到首个可停留段并选中它；只读时只移焦点</td></tr><tr><td><code>End</code></td><td>focus in group, 组未禁用</td><td>焦点移到末个可停留段并选中它；只读时只移焦点</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, 该段未禁用且组非只读</td><td>选中当前段；段是原生 button，这两个键由平台翻成 click</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>held on item, 该段未禁用且组未禁用、非只读</td><td>按住期间该段投影 data-pressed，与指针 :active 同一副按压面；抬起或失焦撤下，按住途中整组转入禁用或只读也撤下。选中与按压互相独立</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根节点是 <code>radiogroup</code>，每一段是 <code>radio</code> 并显式报告 <code>aria-checked</code>。</li><li>整组只占一个 Tab 位，组内靠方向键移动，Home / End 直达首末段；焦点进组时落在已选中的一段。</li><li>禁用的段使用 <code>aria-disabled</code> 而不是原生 <code>disabled</code>：它仍可聚焦，仍是方向键的起点。</li><li>组本身没有可见标题，需要为根节点提供 <code>aria-label</code> 或 <code>aria-labelledby</code>，否则读屏只读出“单选组”。</li><li>指示器是纯装饰，对读屏隐藏；当前段由段自身的选中态表达，指示器不渲染也能读出。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/segmented.css</code> 使用 <code>[data-scope=&quot;segmented&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-block</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-value</code></td><td>context.get(&#39;value&#39;)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-segmented-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-subtle</code></td><td>segmented 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-bg-disabled</code></td><td><code>root</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-muted</code></td><td>segmented 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>transparent</code></td><td>segmented 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-segmented-border-invalid</code></td><td><code>root</code></td><td><code>border-color</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>segmented 的 root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_segmented-font-size</code></td><td>segmented 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-h</code></td><td><code>item</code><br><code>root</code></td><td><code>min-block-size</code></td><td><code>orientation=horizontal</code></td><td><code>--xh-_segmented-h</code></td><td>segmented 的 item、root 部件 min-block-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_segmented-indicator-bg</code></td><td>segmented 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-border</code></td><td><code>indicator</code><br><code>root</code></td><td><code>border</code><br><code>border-color</code></td><td><code>default</code><br><code>tone</code></td><td><code>--xh-_tone</code><br><code>--xh-border-default</code></td><td>segmented 的 indicator、root 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>segmented 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-shadow</code></td><td><code>indicator</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-elevation-raised</code></td><td>segmented 的 indicator 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-shadow-disabled</code></td><td><code>indicator</code><br><code>root</code></td><td><code>box-shadow</code></td><td><code>disabled</code></td><td><code>none</code></td><td>segmented 的 indicator、root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-bg-hover</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>state=checked</code></td><td><code>--xh-bg-subtle-hover</code></td><td>segmented 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-bg-pressed</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>not([data-readonly])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=checked</code></td><td><code>--xh-bg-subtle-active</code></td><td>segmented 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg</code></td><td><code>item</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-checked</code></td><td><code>item</code></td><td><code>color</code></td><td><code>state=checked</code></td><td><code>--xh-_segmented-fg-selected</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-checked-disabled</code></td><td><code>item</code></td><td><code>color</code></td><td><code>disabled</code><br><code>state=checked</code></td><td><code>--xh-_segmented-fg-selected</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-hover</code></td><td><code>item</code></td><td><code>color</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>state=checked</code></td><td><code>--xh-fg-default</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-font-weight</code></td><td><code>item</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>segmented 的 item 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-gap</code></td><td><code>item</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_segmented-gap</code></td><td>segmented 的 item 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-h</code></td><td><code>item</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_segmented-h</code></td><td>segmented 的 item 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-px</code></td><td><code>item</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_segmented-px</code></td><td>segmented 的 item 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>segmented 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>segmented 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-track-padding</code></td><td><code>item</code><br><code>root</code></td><td><code>min-block-size</code><br><code>padding</code></td><td><code>default</code><br><code>orientation=horizontal</code></td><td><code>--xh-space-0_5</code></td><td>segmented 的 item、root 部件 min-block-size、padding 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态 · 指示与换位（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>background-color</code> · <code>block-size</code> · <code>box-shadow</code> · <code>color</code> · <code>inline-size</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>pointer: coarse</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><ul><li>方向从 DOM 读取：整页或某个祖先声明了 <code>dir=&#39;rtl&#39;</code>（或 CSS <code>direction</code>），左右方向键的语义与指示器的起始缘一起翻转，不需要再向组件传递。上下键不受影响。</li><li><code>dir</code> 属性是显式覆盖：提供后以它为准，用于整页 ltr、局部 rtl 的场合。</li><li>指示器的偏移按逻辑起始缘计算，rtl 下自动从右缘计算，不需要另写样式。</li></ul>',67))])}const k=r(s,[["render",h]]);export{f as __pageData,k as default};
